 * `[data-site-name="Menu Item"]` for pages. So ⌘K searched whatever happened to be on screen —
 * on the home feed that is the newest twenty or so; on an article page it is the three cards in
 * the sidebar; on /upgrade it is nothing at all. It never returned a result the reader could not
 * already see, which is the one thing a palette is for. Nothing errored, and the failure mode was
 * a palette that quietly got worse the deeper into the site you went.
 *
 * It reads the SAME `getPosts()` the feed and the search page read, so it cannot drift into being
 * a differently-filtered view of the wire.
 *
 * It sends titles and hrefs only — the same titles the sitemap already carries and the same ones a
 * card shows. Popwire has no member gate and no back-archive split: every story on this site is
 * public, because every story on this site is one the account already posted in public.
 */
export const revalidate = 3600;

/** The real routes, and nothing invented. Matches the chrome — Popwire has four rows in its nav
 * and two of them leave the site, so the palette lists the two that do not. A palette row pointing
 * at a route this app does not serve is a 404 the reader asked for by name. */
const PAGES = [
  { label: 'Home', href: '/', kind: 'Page' },
  { label: 'Search', href: '/search', kind: 'Page' },
];

export async function GET() {
  const posts = await getPosts();
  return NextResponse.json({
    items: [
      ...PAGES,
      ...posts.map((p) => ({
        label: p.title,
        href: `/news/${p.slug}`,
        kind: p.catLabel || 'TRENDING',
      })),
    ],
  });
}
